const out = [];
function walk(n, d) {
  if (d > 7) return;
  let s = "  ".repeat(d) + n.type + " | " + n.name + " | " + n.id + " | " + Math.round(n.width) + "x" + Math.round(n.height);
  if (n.type === "TEXT") s += " | \"" + n.characters.slice(0, 50) + "\" ts=" + (typeof n.textStyleId === "string" ? n.textStyleId.slice(2, 10) : "mixed");
  if (n.type === "INSTANCE") { s += " | main=" + (n.mainComponent?.parent?.type === "COMPONENT_SET" ? n.mainComponent.parent.name + " / " + n.mainComponent.name : n.mainComponent?.name) + " key=" + (n.mainComponent?.key||"").slice(0,8); const p = n.componentProperties; if (p) s += " props=" + JSON.stringify(Object.fromEntries(Object.entries(p).map(([k,v]) => [k, v.value]))).slice(0, 200); }
  if ("layoutMode" in n && n.layoutMode !== "NONE") s += " | AL:" + n.layoutMode;
  out.push(s);
  if ("children" in n) for (const c of n.children) walk(c, d + 1);
}
walk(f, 0);
return out.join("\n");

