const slot = sh.findOne(n => n.type === "SLOT");
notes.push("slot kids before: " + slot.children.map(n => n.name).join(","));
for (const k of [...slot.children]) k.remove();
const body = old.findOne(n => n.name === "Body" && n.type === "FRAME");
slot.appendChild(body); body.layoutSizingHorizontal = "FILL";
try { sh.layoutSizingVertical = "HUG"; } catch (e) { notes.push("sheet hug: " + e.message); }
try { slot.layoutSizingVertical = "HUG"; } catch (e) { notes.push("slot hug: " + e.message); }
const title = sh.findOne(n => n.type === "TEXT" && n.parent && n.parent.name === "Title");
