const hi = homeMain.createInstance(); f.appendChild(hi); hi.layoutSizingHorizontal = "FILL";
try { hi.setProperties(Object.fromEntries(Object.entries(ref.children.find(n => n.name === "Home Indicator").componentProperties).map(([k, v]) => [k, v.value]))); } catch (e) { notes.push("hi: " + e.message); }
// old home indicator in body? body had none (home was on frame). remove old frame
old.remove();
await f.screenshot({ scale: 0.55 });
return { id: f.id, h: f.height, sheetH: sh.height, notes };

