const sec = await figma.getNodeByIdAsync("12037:143143");
const lines = [];
const kids = [...sec.children].sort((a, b) => (a.y - b.y) || (a.x - b.x));
for (const n of kids) {
  const base = `${n.type[0]} ${n.id} "${n.name.slice(0, 40)}" @${Math.round(n.x)},${Math.round(n.y)} ${Math.round(n.width)}x${Math.round(n.height)}`;
  if (n.type === "TEXT") { lines.push("T " + n.id + " @" + Math.round(n.x) + "," + Math.round(n.y) + " " + n.characters.slice(0, 50).replace(/\n/g, " ")); continue; }
  if (!("findAll" in n)) { lines.push(base); continue; }
  let pres = "";
  const all = n.findAll(() => true);
  const inst = all.filter(x => x.type === "INSTANCE");
  if (inst.some(x => x.name.startsWith("Sheet"))) pres += "SHEET ";
  if (inst.some(x => x.name === "Navigation Bar")) pres += "NAV ";
  if (all.some(x => /Bottom Sheet|Dim/i.test(x.name))) pres += "OVERLAY ";
  const btns = inst.filter(x => x.name === "Block Button").map(x => { const t = x.findOne(y => y.type === "TEXT"); return t ? t.characters.slice(0, 14) : "?"; });
  const reacts = all.filter(x => x.reactions && x.reactions.length).length + (n.reactions?.length ? 1 : 0);
  const generic = all.filter(x => /^(Frame|Group|Rectangle|Ellipse|Vector) ?\d*$/.test(x.name)).length;
  lines.push(`${base} [${pres.trim()}] btn:${btns.join("/")} react:${reacts} generic:${generic}`);
}
return lines.join("\n");

