const log = [];
const loadT = async t => { for (const s of t.getStyledTextSegments(["fontName"])) await figma.loadFontAsync(s.fontName); };
const N = async id => await figma.getNodeByIdAsync(id);
const SA = (d = 0.35, e = "EASE_OUT") => ({ type: "SMART_ANIMATE", easing: { type: e }, duration: d });
const DIS = (d = 0.25) => ({ type: "DISSOLVE", easing: { type: "EASE_OUT" }, duration: d });
const go = (dest, tr) => ({ type: "NODE", destinationId: dest, navigation: "NAVIGATE", transition: tr || SA(), resetScrollPosition: true });
const BACK = { type: "BACK" };
async function link(node, action, label, trigger = { type: "ON_CLICK" }) {
  if (!node) { log.push("✗ missing: " + label); return; }
  try { await node.setReactionsAsync([{ trigger, actions: [action] }]); log.push("✓ " + label); } catch (e) { log.push("✗ " + label + ": " + e.message); }
}
const btn = (root, txt) => { const t = root.findOne(n => n.type === "TEXT" && n.characters === txt); if (!t) return null; let p = t.parent; while (p && !(p.type === "INSTANCE" && p.name === "Block Button")) p = p.parent; return p || t; };
const lead = root => root.findOne(n => n.name === "Leading Button");

// destinations
const CAM = "11899:52173", DEX = "11997:83897", DEX_DETAIL = "11997:81599";
const B14a = await N("12231:7001"), B14b = await N("12231:7076"), B14c = await N("12231:7195");
const B10a = await N("12152:99433"), B10b = await N("12152:99499");
const G1 = await N("12236:7014"), G2 = await N("12235:7205"), C19c = await N("12119:84744");

// ---- B-14 flow
await link(btn(B14a, "도감에 등록하기"), go(B14b.id, SA(0.35)), "B-14a 등록하기 → B-14b");
