    if (tx.characters === "누끼") { t.remove(); continue; }
    if (tx.characters === "카드") { tx.characters = "메탈 카드"; t.name = "Tab · 메탈 카드"; }
    if (tx.characters === "엽서") { tx.characters = "우표"; t.name = "Tab · 우표"; }
    if (t.layoutMode !== "NONE") { t.primaryAxisSizingMode = "AUTO"; t.paddingLeft = Math.max(t.paddingLeft, 12); t.paddingRight = Math.max(t.paddingRight, 12); }
