  const body = F.children.find(n => n.name === "Body");
  const old = body.children.find(n => n.type === "INSTANCE");
  const inst = comp.createInstance(); body.insertChild(body.children.indexOf(old), inst); old.remove();
  const ctaT = TX(F.children.find(n => n.name === "CTA"))[0]; await loadT(ctaT); ctaT.characters = cta;
  return tabs;
}
