const sp = n => figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", VN(n));
const alias = n => figma.variables.createVariableAlias(VN(n));
const grad = (node, stops, tf) => ({ type: "GRADIENT_LINEAR", gradientTransform: tf || [[1, 0, 0], [0, 1, 0]], gradientStops: stops.map(([pos, name]) => { const r = VN(name).resolveForConsumer(node).value; return { position: pos, color: { r: r.r, g: r.g, b: r.b, a: r.a ?? 1 }, boundVariables: { color: alias(name) } }; }) });
const log = [];
// 1) Title Card restyle
const tc = await figma.getNodeByIdAsync("12212:85786");
tc.cornerRadius = 28; tc.clipsContent = true;
tc.fills = [grad(tc, [[0, "neutral/700"], [0.5, "neutral/1000"], [1, "neutral/800"]], [[0.6, 0.8, -0.2], [-0.8, 0.6, 0.6]])];
tc.strokes = [sp("neutral/alpha/light20")]; tc.strokeWeight = 1; tc.strokeAlign = "INSIDE";
const em = tc.findAll(n => n.name === "Level Emblem")[0];
em.fills = [grad(em, [[0, "gold/100"], [0.5, "gold/500"], [1, "goldDeep/500"]])];
em.strokes = [sp("neutral/alpha/light40")]; em.strokeWeight = 3; em.strokeAlign = "OUTSIDE";
em.effects = [{ type: "DROP_SHADOW", color: { r: 0.9, g: 0.7, b: 0.2, a: 0.45 }, offset: { x: 0, y: 0 }, radius: 36, spread: 4, visible: true, blendMode: "NORMAL" }];
for (const t of tc.findAll(n => n.type === "TEXT")) {
  if (t.name === "Lv.5") t.fills = [sp("neutral/1000")];
  else if (t.name === "관찰하는 조류 탐험가") t.fills = [sp("neutral/0")];
  else t.fills = [sp(t.name === "Moalog" ? "gold/100" : "neutral/alpha/light60")];
}
const inner = figma.createRectangle(); inner.name = "Inner Line"; tc.appendChild(inner); inner.layoutPositioning = "ABSOLUTE";
inner.x = 10; inner.y = 10; inner.resize(340, 340); inner.cornerRadius = 20; inner.fills = []; inner.strokes = [sp("neutral/alpha/light10")]; inner.strokeWeight = 1;
