function mk(col,name,val,scopes){ let v=all.find(x=>x.name===name&&x.variableCollectionId===col.id); if(!v){v=figma.variables.createVariable(name,col,'COLOR');} v.scopes=scopes; for(const m of col.modes) v.setValueForMode(m.modeId,val); return v;}
const sc=['FRAME_FILL','SHAPE_FILL','STROKE_COLOR'];
