const gA1=mk(alias,'gradient/ai/1',A(cyan),sc);
const gA2=mk(alias,'gradient/ai/2',A(mist),sc);
const gA3=mk(alias,'gradient/ai/3',A(teal),sc);
const gA4=mk(alias,'gradient/ai/4',A(sec),sc);
const styles=await figma.getLocalPaintStylesAsync();
const up=styles.find(s=>s.name==='Upgrade');
const bind=(stop,v)=>({...stop,boundVariables:{color:A(v)}});
const p=JSON.parse(JSON.stringify(up.paints[0]));
p.gradientStops=[bind(p.gradientStops[0],gUpS),bind(p.gradientStops[1],gUpE)];
up.paints=[p];
// AI Aurora style
