ai.paints=[{type:'GRADIENT_ANGULAR',gradientTransform:[[1,0,0],[0,1,0]],gradientStops:[
 {position:0,color:{r:20/255,g:243/255,b:232/255,a:1},boundVariables:{color:A(gA1)}},
 {position:0.26,color:{r:244/255,g:244/255,b:244/255,a:1},boundVariables:{color:A(gA2)}},
 {position:0.56,color:{r:81/255,g:205/255,b:165/255,a:1},boundVariables:{color:A(gA3)}},
 {position:0.77,color:{r:196/255,g:235/255,b:67/255,a:1},boundVariables:{color:A(gA4)}},
 {position:1,color:{r:20/255,g:243/255,b:232/255,a:1},boundVariables:{color:A(gA1)}}]}];
ai.description='척척박사·AI 포인트. 움직이는 테두리(FX)에 사용. 정지점은 gradient/ai/1~4 변수';
