await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const g=id=>figma.getNodeByIdAsync(id);
const ICON={'⋯':['12157:112129',24],'▶':['3032:22436',12],'❚❚':['3032:22430',14],'✓':['3032:22009',14]};
const roots=['12259:96953','12259:96986','12263:91336'];
const done=[];
for(const rid of roots){
  const r=await g(rid);
  const texts=r.findAllWithCriteria({types:['TEXT']}).filter(t=>ICON[t.characters.trim()]);
  for(const t of texts){
    const [cid,sz]=ICON[t.characters.trim()];
    const comp=await g(cid); const ins=comp.createInstance();
    const p=t.parent; const idx=p.children.indexOf(t);
    const cxp=t.x+t.width/2, cyp=t.y+t.height/2;
    p.insertChild(idx,ins); ins.rescale(sz/ins.width); ins.name=comp.name;
    const fill=JSON.parse(JSON.stringify(t.fills));
    ins.findAll(n=>'fills' in n && n.type!=='INSTANCE' && n.fills.length).forEach(v=>v.fills=fill);
    if(!p.layoutMode||p.layoutMode==='NONE'){ ins.x=cxp-ins.width/2; ins.y=cyp-ins.height/2; }
    t.remove(); done.push(rid+':'+comp.name);
  }
}
// 대표 Mark contents
const marks=(await g('12263:91336')).findAll(n=>n.name==='대표 Mark').map(m=>m.children.map(c=>c.type+':'+(c.characters||c.name)));
return {done,marks};

