  const su=figma.createText(); su.fontName=ft; su.fontSize=13; su.characters='점'; su.fills=greyTxt; su.name='Score Unit';
  const scw=figma.createAutoLayout('HORIZONTAL'); scw.name='Score'; scw.fills=[]; scw.itemSpacing=2; scw.counterAxisAlignItems='BASELINE'; scw.appendChild(sc); scw.appendChild(su);
