  const bot=figma.createRectangle(); bot.name='Bottom Scrim'; v.insertChild(1,bot); bot.resize(393,280); bot.y=220; bot.fills=await grad(false);
  for(const nm of ['Back','More']){ const b=v.findChild(n=>n.name===nm); b.fills=glass; b.strokes=glassS; b.effects=[]; b.findAll(n=>n.type==='VECTOR'||n.type==='BOOLEAN_OPERATION').forEach(x=>x.fills=W);}
  const tabs=v.findChild(n=>n.name==='Tabs'); tabs.fills=glass; tabs.strokes=glassS;
  tabs.findAllWithCriteria({types:['TEXT']}).forEach(t=>{ if(!t.parent.fills.length) t.fills=W; });
  const live=card.findChild(n=>n.name==='Live'); v.appendChild(live); live.x=16; live.y=118;
  const id=card.findChild(n=>n.name==='Identity'); v.appendChild(id); id.x=20; id.y=372;
  id.findAllWithCriteria({types:['TEXT']}).forEach(t=>{ if(t.characters.startsWith('Cosmos')) t.fills=W80; else if(t.parent===id) t.fills=W; });
  const no=id.findOne(n=>n.name==='Chip · No.049'); no.fills=[await sp('VariableID:7545:55934',{r:1,g:1,b:1})]; no.findAllWithCriteria({types:['TEXT']}).forEach(t=>t.fills=W);
  const prog=card.findChild(n=>n.name==='Live Progress'); v.appendChild(prog); prog.resize(361,3); prog.x=16; prog.y=480;
  // grade: emblem + score pill
  const grade=figma.createAutoLayout('VERTICAL'); grade.name='Grade'; grade.fills=[]; grade.itemSpacing=4; grade.counterAxisAlignItems='CENTER'; v.appendChild(grade);
  const em=emS.createInstance(); em.name='Grade Emblem'; grade.appendChild(em);
  const pill=figma.createAutoLayout('HORIZONTAL'); pill.name='Score'; pill.fills=glass; pill.cornerRadius=999; pill.paddingLeft=pill.paddingRight=8; pill.paddingTop=pill.paddingBottom=2; pill.itemSpacing=1; pill.counterAxisAlignItems='BASELINE';
  const s1=figma.createText(); s1.fontName=bold; s1.fontSize=14; s1.characters='93'; s1.fills=W;
  const s2=figma.createText(); s2.fontName=ft; s2.fontSize=11; s2.characters='점'; s2.fills=W80;
  pill.appendChild(s1); pill.appendChild(s2); grade.appendChild(pill);
  grade.x=393-16-grade.width; grade.y=id.y+id.height-grade.height;
  card.remove();
  if(isLive){ id.visible=false; grade.visible=false; prog.visible=true; } else prog.visible=false;
  res.push(v.id);
}
const gal=await g('12256:96675'); const hero=await g('12260:96956'); const row=await g('12264:91293'); row.y=500; gal.resize(393,606);
