const all=(await figma.variables.getLocalVariablesAsync('FLOAT')).filter(v=>v.variableCollectionId==='VariableCollectionId:3003:12009');
const byId=Object.fromEntries(all.map(v=>[v.id,v]));
const res=v=>{let x=v.valuesByMode[Object.keys(v.valuesByMode)[0]]; let n=0; while(typeof x==='object'&&n<5){const t=byId[x.id]; x=t?t.valuesByMode[Object.keys(t.valuesByMode)[0]]:'?'; n++;} return x;};
return all.filter(v=>/^(gap|padding|radius|margin|sizing)/.test(v.name)).map(v=>v.name+'='+res(v)+' '+v.id);

