const items=[];
async function keep(nodeId,label,fix){ const n=await g(nodeId); const inst=n.type==='COMPONENT_SET'?n.defaultVariant.createInstance():n.createInstance(); const f=inst.detachInstance(); f.name='[보관] '+label; if(fix) await fix(f); sec.appendChild(f); f.rescale(0.5); items.push(f); return f;}
await keep('11053:36186','CategoryCard/Asset · 원래 PNG 배지 왼쪽 위', async f=>{ const e=f.findOne(n=>n.name==='Grade Emblem'); const b=(await g('11298:61874')).createInstance(); f.appendChild(b); b.layoutPositioning='ABSOLUTE'; b.resize(32,38); b.x=6; b.y=6; b.name='Grade Badge'; e.remove(); });
await keep('12259:96953','Detail/Hero · 전체 사진 393×500');
await keep('12243:95438','Share/Metal Card · Shine=Start');
const orig=await g('11997:81599'); 
let x=40; for(const f of items){ f.x=x; f.y=80; x+=f.width+40; }
sec.resizeWithoutConstraints(x, 80+Math.max(...items.map(i=>i.height))+40);
const note=figma.createText(); await figma.loadFontAsync({family:'Inter',style:'Regular'}); note.characters='되돌릴 때: 이 사본을 참고해 원본 컴포넌트를 다시 맞춘다. 사용자 원안 상세 화면은 C-06 (11997:81599) 그대로 남아 있음.'; note.fontSize=14; sec.appendChild(note); note.x=40; note.y=30;
return {sec:sec.id, items:items.map(i=>i.id+' '+i.name)};

