await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const g=id=>figma.getNodeByIdAsync(id);
const V={}; for(const [k,id] of Object.entries({gxs:'9131:33400',gs:'9131:33401',gm:'9131:33402',pm:'3003:12025',ps:'3003:12024',pxs:'3003:12023',pxxs:'7179:13955',rf:'7002:3888'})) V[k]=await figma.variables.getVariableByIdAsync('VariableID:'+id);
const B=(n,f,v)=>n.setBoundVariable(f,v);
const AL=(name,dir)=>{const f=figma.createFrame(); f.name=name; f.layoutMode=dir; f.fills=[]; f.clipsContent=false; f.primaryAxisSizingMode='AUTO'; f.counterAxisSizingMode='AUTO'; return f;};
const out=[];
for(const vid of ['12259:96953','12259:96986']){
  const v=await g(vid); const isLive=vid==='12259:96986';
  for(const t of v.findAllWithCriteria({types:['TEXT']})) for(const s of t.getStyledTextSegments(['fontName'])) await figma.loadFontAsync(s.fontName);
  const c=nm=>v.findChild(n=>n.name===nm);
  const top=c('Top Scrim'), bot=c('Bottom Scrim'), back=c('Back'), tabs=c('Tabs'), more=c('More'), live=c('Live'), id=c('Identity'), prog=c('Live Progress'), grade=c('Grade');
  // header
  const header=AL('Header','HORIZONTAL'); header.primaryAxisAlignItems='SPACE_BETWEEN'; header.counterAxisAlignItems='CENTER';
  v.appendChild(header); header.appendChild(back); header.appendChild(tabs); header.appendChild(more);
  const topG=AL('Top','VERTICAL'); B(topG,'itemSpacing',V.gm); topG.counterAxisAlignItems='MIN'; v.appendChild(topG); topG.appendChild(header); topG.appendChild(live);
  // identity
  id.layoutMode='VERTICAL'; id.primaryAxisSizingMode='AUTO'; id.counterAxisSizingMode='FIXED'; B(id,'itemSpacing',V.gxs); id.fills=[];
  const chips=id.findChild(n=>n.name==='Chips'); chips.layoutMode='HORIZONTAL'; chips.primaryAxisSizingMode='AUTO'; chips.counterAxisSizingMode='AUTO'; B(chips,'itemSpacing',V.gxs);
  const info=AL('Info','HORIZONTAL'); info.counterAxisAlignItems='MAX'; B(info,'itemSpacing',V.gs); 
  info.appendChild(id); info.appendChild(grade);
  const botG=AL('Bottom','VERTICAL'); B(botG,'itemSpacing',V.ps); v.appendChild(botG); botG.appendChild(info); botG.appendChild(prog);
  // root
  v.layoutMode='VERTICAL'; v.primaryAxisAlignItems='SPACE_BETWEEN'; v.counterAxisAlignItems='MIN';
  v.primaryAxisSizingMode='FIXED'; v.counterAxisSizingMode='FIXED';
  v.paddingTop=62; B(v,'paddingLeft',V.pm); B(v,'paddingRight',V.pm); B(v,'paddingBottom',V.pm);
  for(const s of [top,bot]){ s.layoutPositioning='ABSOLUTE'; }
  v.resize(393,393);
  top.x=0; top.y=0; top.resize(393,170); top.constraints={horizontal:'STRETCH',vertical:'MIN'};
  bot.resize(393,230); bot.x=0; bot.y=393-230; bot.constraints={horizontal:'STRETCH',vertical:'MAX'};
  topG.layoutSizingHorizontal='FILL'; header.layoutSizingHorizontal='FILL'; botG.layoutSizingHorizontal='FILL'; info.layoutSizingHorizontal='FILL';
  id.layoutSizingHorizontal='FILL';
  for(const t of id.findAllWithCriteria({types:['TEXT']})){ if(t.parent===id){ t.layoutSizingHorizontal='FILL'; t.textAutoResize='HEIGHT'; t.textTruncation='ENDING'; t.maxLines=1; } }
  prog.layoutMode='HORIZONTAL'; prog.primaryAxisSizingMode='FIXED'; prog.counterAxisSizingMode='FIXED'; prog.layoutSizingHorizontal='FILL'; prog.resize(prog.width,3); prog.cornerRadius=2;
  if(isLive){ const f=prog.findChild(n=>n.name==='Fill'); f.layoutGrow=0; f.resize(200,3);}  
  if(!isLive){ prog.visible=false; }
  try{ v.lockAspectRatio(); }catch(e){ v.targetAspectRatio={x:1,y:1}; }
  out.push({v:v.id,h:v.height,ar:v.targetAspectRatio});
}
return out;

