  v.appendChild(info); info.layoutSizingHorizontal='FILL'; info.counterAxisAlignItems='CENTER'; info.paddingLeft=4; info.paddingRight=4; info.paddingTop=4;
  id.visible=true; id.opacity=1;
  for(const t of id.findAllWithCriteria({types:['TEXT']})){ if(t.parent===id){ t.fills = t.characters.startsWith('Cosmos')? cp(GREYT):cp(DARK); } }
  const no=id.findOne(n=>n.name==='Chip · No.049'); no.fills=cp(GREYB); no.findAllWithCriteria({types:['TEXT']}).forEach(t=>t.fills=cp(GREYT));
  const nw=id.findOne(n=>n.name==='Chip · NEW'); nw.fills=cp(DARK); nw.findAllWithCriteria({types:['TEXT']}).forEach(t=>t.fills=cp(W));
  // grade: bigger emblem + score
  grade.children.forEach(c=>c.remove());
  grade.layoutMode='HORIZONTAL'; grade.setBoundVariable('itemSpacing',VV.gs); grade.counterAxisAlignItems='CENTER'; grade.fills=[];
  const em=emS.createInstance(); em.name='Grade Emblem'; grade.appendChild(em);
  const sc=AL('VERTICAL','Score'); sc.itemSpacing=0; sc.counterAxisAlignItems='MIN';
  const n1=AL('HORIZONTAL','Score Value'); n1.counterAxisAlignItems='BASELINE'; n1.itemSpacing=1;
  const a=figma.createText(); a.fontName=Bd; a.fontSize=24; a.characters='93'; a.fills=cp(DARK); n1.appendChild(a);
  const u=figma.createText(); u.fontName=R; u.fontSize=13; u.characters='점'; u.fills=cp(GREYT); n1.appendChild(u);
  const lb=figma.createText(); lb.fontName=R; lb.fontSize=11; lb.characters='포착 점수'; lb.fills=cp(GREYT);
