await W(inF(C01,/^Segmented Controls$/,0),sheet('12118:83268'),'C-01 정렬');
await W(C01.findAll(n=>n.name==='Floating Action Button')[0],push(b01.id),'C-01 FAB');
const cards=C01.findAll(n=>n.name==='CategoryCard'&&n.type==='INSTANCE');
await W(cards[0],push('12256:96670'),'C-01 card1→C-06'); await W(cards[1],push(f1.id),'C-01 card2→C-06f');
// C-13 empty
const C13=await g('12115:83833'); await W(C13.findAll(n=>n.name==='Floating Action Button')[0],push(b01.id),'C-13 FAB');
// search
const A=await g('12115:83919'), B=await g('12115:84003'), N=await g('12115:84076');
const chipsA=A.findAll(n=>n.name==='Chip-item'); await W(chipsA[0],nav('12115:84003'),'C-14a chip1→b'); await W(chipsA[chipsA.length-1],nav('12115:84076'),'C-14a chip4→c');
for(const [fr,l] of [[A,'a'],[B,'b']]){ const rows=fr.findAll(n=>n.name==='Dex/Search Result Row'); if(rows[0]) await W(rows[0],push('12256:96670'),'C-14'+l+' row1→C-06'); }
await W(B.findAll(n=>n.name==='Dex/Search Result Row')[1],push('12261:97113'),'C-14b row2→C-05');
// 척척박사
const a=await g('12119:84601'), b=await g('12119:84675');
const ca=a.findAll(n=>n.name==='Chip-item'); for(let i=0;i<ca.length;i++) await W(ca[i],nav('12119:84675'),'C-19a chip'+i);
const cb=b.findAll(n=>n.name==='Chip-item'); for(let i=0;i<cb.length;i++) await W(cb[i],nav('12119:84744'),'C-19b chip'+i);
return log;

