await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const g=id=>figma.getNodeByIdAsync(id);
const comps=await g('12199:85019'); const trash=await g('12280:128877');
const head=comps.children.find(c=>c.type==='TEXT'&&c.characters.startsWith('도감'));
await figma.loadFontAsync(head.fontName);
const bottom=Math.max(...comps.children.map(c=>c.y+c.height));
const mkHead=(txt,y)=>{ const t=head.clone(); comps.appendChild(t); t.characters=txt; t.x=head.x; t.y=y; t.name='heading · '+txt; return t; };
let y=bottom+120; const moved=[];
mkHead('도감 상세 · 사진',y); y+=head.height+40;
let x=head.x;
for(const id of ['12259:97032','12263:91336','12274:91634','12277:91918']){ const n=await g(id); comps.appendChild(n); n.x=x; n.y=y; x+=n.width+80; moved.push(n.name); }
y+=520; x=head.x;
mkHead('공유 (카드 · 시트용)',y); y+=head.height+40;
for(const id of ['12212:85774','12212:85786','12243:95484','12243:95487']){ const n=await g(id); comps.appendChild(n); n.x=x; n.y=y; x+=n.width+80; moved.push(n.name); }
// 폐기 컴포넌트 → trash
let tx=5315; for(const id of ['12214:85927','12214:85958']){ const n=await g(id); trash.appendChild(n); n.x=tx; n.y=4500; tx+=n.width+40; moved.push('trash:'+n.name.slice(0,20)); }
comps.name='Components · 앱 로컬 컴포넌트';
const docs=await g('12135:100942'); docs.name='문서 · 시스템 · 뱃지 · 레벨 · 정책';
return {moved,bottom,newH:comps.height};

