await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const flow=await figma.getNodeByIdAsync('12037:143143');
const kids=[...flow.children];
const isFrame=n=>['FRAME','COMPONENT','COMPONENT_SET','INSTANCE'].includes(n.type)&&n.height>=300;
const fy=kids.filter(isFrame).map(n=>n.y).sort((a,b)=>a-b);
const clusters=[]; for(const y of fy){ const c=clusters[clusters.length-1]; if(c&&y-c.max<=80){ c.max=y; } else clusters.push({min:y,max:y}); }
const keyOf=n=>{ if(isFrame(n)){ const c=clusters.find(c=>n.y>=c.min-1&&n.y<=c.max+1); return c.min; } const c=clusters.find(c=>c.min>=n.y-5); return c?c.min:1e9; };
const bandOf=n=>{ const y=keyOf(n); return y<1300?0:y<3900?1:y<10000?2:y<13800?3:y<15000?4:y<16100?5:6; };
// text headings of bands must stay with their band: heading y100 key=200 ok; 'Ⓑ 카메라' y1300 key=1432 ->B ok
const names=['Ⓐ 온보딩 · 로그인 · 가입','Ⓑ 카메라 · 포착','Ⓒ 나의 도감 · 상세 · 척척박사','Ⓓ 리포트','Ⓔ 레벨 · 뱃지 · 출석','Ⓕ 공유','Ⓖ 프리미엄 · 이용권'];
const sorted=kids.map(n=>({n,k:keyOf(n),b:bandOf(n)})).sort((a,b)=>a.k-b.k||a.n.y-b.n.y||a.n.x-b.n.x);
// z-order = reverse flow order
for(const s of sorted) flow.insertChild(0,s.n);
const counts=[]; const groups=[];
for(let b=0;b<7;b++){ const items=sorted.filter(s=>s.b===b).map(s=>s.n); if(!items.length){counts.push(0);continue;}
  const grp=figma.group(items,flow); grp.name=names[b]; 
  // keep inner order = reverse flow order
  for(const it of items) grp.insertChild(0,it);
  groups.push(grp); counts.push(items.length); }
// top-level group order: Ⓐ on top of panel
for(const grp of groups) flow.insertChild(0,grp);
return {counts,groups:groups.map(g=>g.name+' '+g.children.length),flowKids:flow.children.length};

