await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const flow=await figma.getNodeByIdAsync('12037:143143');
const c=flow.children.find(n=>n.name.startsWith('Ⓒ'));
const rows=c.children.filter(n=>n.y>=6300&&n.y<9700).sort((a,b)=>a.y-b.y||a.x-b.x).map(n=>n.type[0]+':'+n.name.slice(0,28)+' ('+Math.round(n.x)+','+Math.round(n.y)+')');
// overlap check among frames in whole flow
const fr=[]; for(const g of flow.children) for(const n of g.children) if(n.height>=300) fr.push(n);
const overlaps=[]; for(let i=0;i<fr.length;i++) for(let j=i+1;j<fr.length;j++){ const a=fr[i],b=fr[j]; const ox=Math.min(a.x+a.width,b.x+b.width)-Math.max(a.x,b.x), oy=Math.min(a.y+a.height,b.y+b.height)-Math.max(a.y,b.y); if(ox>10&&oy>10) overlaps.push(a.name.slice(0,18)+' × '+b.name.slice(0,18)); }
return {rows,overlaps:overlaps.slice(0,20),count:overlaps.length};

