const flow=await figma.getNodeByIdAsync('12037:143143');
const groups=[...flow.children].filter(n=>n.type==='GROUP');
const out=[];
for(const grp of groups.slice().reverse()){ // G..A so Ⓐ ends on top of panel
  const items=[...grp.children];
  const abs=items.map(n=>({n,x:n.absoluteTransform[0][2],y:n.absoluteTransform[1][2],w:n.width,h:n.height}));
  const minX=Math.min(...abs.map(a=>a.x)), minY=Math.min(...abs.map(a=>a.y)), maxX=Math.max(...abs.map(a=>a.x+a.w)), maxY=Math.max(...abs.map(a=>a.y+a.h));
  const P=40;
  const sec=figma.createSection(); sec.name=grp.name; sec.x=minX-P; sec.y=minY-P-20; sec.resizeWithoutConstraints(maxX-minX+P*2,maxY-minY+P*2+20);
  for(const a of abs){ sec.appendChild(a.n); a.n.x=a.x-sec.x; a.n.y=a.y-sec.y; }
  out.push(sec.name+' '+abs.length+' @'+Math.round(sec.x)+','+Math.round(sec.y)+' '+Math.round(sec.width)+'x'+Math.round(sec.height));
  grp.remove();
}
const left=flow.children.length;
if(left===0) flow.remove();
return {out,flowLeft:left};

