const sec=await figma.getNodeByIdAsync('12295:99931');
const re=/Button|Chip-item|Tab-item|Tab Bar Button|Row|Segmented Controls$|Search Field|CategoryCard$|Btn ·|Thumb|Floating|Toast|Dimmed$|^Dim$|Q ·|Dock/;
const out={};
for(const f of sec.children){ if(!(f.type==='FRAME'||f.type==='COMPONENT')||f.height<700) continue;
  const miss=[]; const seen=new Set();
  for(const n of f.findAll(x=>re.test(x.name)&&x.visible)){
    // skip nested deeper duplicates: only top-most matching
    let p=n.parent, dup=false; while(p&&p!==f){ if(re.test(p.name)&&!/Button$/.test(p.name)){dup=true;break;} p=p.parent; } if(dup) continue;
    const has=(n.reactions&&n.reactions.length)||n.findAll(c=>c.reactions&&c.reactions.length).length;
    if(has) continue;
    const label=(n.type==='TEXT'?n.characters:(n.findOne(t=>t.type==='TEXT')?.characters||'')).slice(0,12);
    const key=n.name.slice(0,14)+':'+label; if(seen.has(key)) continue; seen.add(key); miss.push(key);
  }
  if(miss.length) out[f.name.slice(0,26)]=miss.slice(0,9);
}
return out;

