await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const g=id=>figma.getNodeByIdAsync(id);
const sec=await g('12295:99931');
const byName=re=>sec.findAll(n=>re.test(n.name)&&(n.type==='FRAME'||n.type==='COMPONENT')&&Math.round(n.width)===393)[0];
const sa={type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.25};
const nav=(d,tr)=>({trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:d,navigation:'NAVIGATE',transition:tr||sa,preserveScrollPosition:false,resetVideoPosition:false}]});
const back={trigger:{type:'ON_CLICK'},actions:[{type:'BACK'}]};
const log=[]; const W=async(n,r,l)=>{ if(!n){log.push('MISSING '+l);return;} try{ await n.setReactionsAsync([r]); log.push('ok '+l);}catch(e){ log.push('ERR '+l+' '+e.message.slice(0,40)); } };
const C06=(await g('12256:96670')).id;
// 1 되돌리기
const d06=byName(/^C-06d/); await W(d06.findAll(n=>n.name==='Inline-Button')[0],nav(C06),'C-06d 되돌리기');
// 2 C-15 정렬 시트
const c15=await g('12118:83268'); const dim=c15.children.find(n=>/Dimmed|Dim/.test(n.name)); await W(dim,nav('11997:83897'),'C-15 dim');
const opts=c15.findAll(n=>/Radio|Sort|Option|Row/.test(n.name)&&n.type!=='TEXT'&&n.type!=='VECTOR'&&n.visible);
log.push('c15 opts '+opts.length+': '+opts.slice(0,6).map(n=>n.name.slice(0,14)).join(','));
// 3 C-13
const c13=await g('12115:83833'); const tabs13=c13.findAll(n=>n.name==='Tab-item');
await W(tabs13[1],nav('12208:85096'),'C-13 리포트 탭');
await W(c13.findAll(n=>n.name==='Icon Button'&&n.type==='FRAME')[0]||c13.findAll(n=>/Icon Button/.test(n.name))[0],nav('12236:7014',{type:'MOVE_IN',direction:'BOTTOM',matchLayers:false,easing:{type:'EASE_OUT'},duration:0.3}),'C-13 Upgrade');
// 4 C-14 back
for(const id of ['12115:83919','12115:84003','12115:84076']){ const f=await g(id); await W(f.findAll(n=>n.name==='Icon Button')[0],back,'C-14 back '+id); }
const rows=(await g('12115:83919')).findAll(n=>n.name==='Dex/Search Result Row'); for(let i=1;i<rows.length;i++) await W(rows[i],nav(C06),'C-14a row'+(i+1));
const rb=(await g('12115:84003')).findAll(n=>n.name==='Dex/Search Result Row'); await W(rb[2],nav(C06),'C-14b row3');
// 5 자세히 link + FAB
const c01=await g('11997:83897'); const more=c01.findAll(n=>n.type==='TEXT'&&/^자세히/.test(n.characters))[0]; await W(more,nav('11997:112192'),'C-01 자세히');
const st=await g('11997:112192'); await W(st.findAll(n=>n.name==='Floating Action Button')[0],nav('11845:59610'),'C-01s FAB');
// 6 척척박사 전송
for(const [id,dst] of [['12119:84601','12119:84675'],['12119:84675','12119:84744']]){ const f=await g(id); await W(f.findAll(n=>n.name==='Icon-Button')[0],nav(dst),'C-19 send '+id); }
return log;

