await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
const goldIds=new Set(['VariableID:12179:6989','VariableID:12179:6990','VariableID:12179:6991','VariableID:12179:6992','VariableID:12179:6993','VariableID:12179:6994']);
const styles=(await figma.getLocalPaintStylesAsync()); const goldStyle=new Set(styles.filter(s=>/Gold|Yellow/.test(s.name)).map(s=>s.id));
const isGoldRGB=c=>c&&c.r>0.7&&c.g>0.55&&c.g<0.85&&c.b<0.45&&c.r-c.b>0.35;
const skip=new Set(['12280:128877','11827:40538','11957:51193']);
const res={}; const oldBadge={};
for(const sec of figma.currentPage.children){ if(sec.type!=='SECTION'||skip.has(sec.id)) continue;
  for(const top of sec.children){ if(!('findAll' in top)) continue;
    let gold=0, png=0;
    const nodes=[top,...top.findAll(()=>true)];
    for(const n of nodes){
      if(n.fillStyleId&&goldStyle.has(n.fillStyleId)) gold++;
      for(const k of ['fills','strokes']){ const arr=n[k]; if(!arr||!arr.map) continue; for(let i=0;i<arr.length;i++){ const p=arr[i]; if(p.type==='SOLID'&&p.visible!==false){ const bv=n.boundVariables?.[k]?.[i]; if((bv&&goldIds.has(bv.id))||(!bv&&isGoldRGB(p.color))) gold++; } if(p.type==='GRADIENT_LINEAR'&&p.gradientStops){ const bvs=p.gradientStops.filter(s=>(s.boundVariables?.color&&goldIds.has(s.boundVariables.color.id))); if(bvs.length) gold++; } } }
      if(n.type==='INSTANCE'&&n.name==='Grade Badge'&&n.visible) png++;
    }
    if(gold) (res[sec.name.slice(0,8)]=res[sec.name.slice(0,8)]||[]).push(top.name.slice(0,26)+' ×'+gold);
    if(png) (oldBadge[sec.name.slice(0,8)]=oldBadge[sec.name.slice(0,8)]||[]).push(top.name.slice(0,26)+' ×'+png);
  } }
return {gold:res,oldBadge};

