  if(n.children&&n.type!=='TEXT'&&!(n.type==='INSTANCE'&&d>=3&&!/safe/.test(n.name))) for(const c of n.children) walk(c,d+1,max); };
for(const id of ['12152:99433','12231:7001']){ lines.push('=== '+id); const f=await figma.getNodeByIdAsync(id); walk(f,0,6); }
