const GR={S:'12277:91883',A:'12277:91888',B:'12277:91893',C:'12277:91898',D:'12277:91903',E:'12277:91908',F:'12277:91913'};
const log={};
async function apply(frameId,cfg){
  const f=await g(frameId); const sheet=f.children.find(c=>c.type==='INSTANCE'&&/Sheet/.test(c.name)); const slot=sheet.children.find(c=>c.type==='SLOT'); const content=slot.children.find(c=>c.name==='content');
  const cam=content.children.find(c=>c.name==='Camera Image'), msg=content.children.find(c=>c.name==='Message');
  const texts=msg.findAll(t=>t.type==='TEXT').map(t=>t.characters);
  cam.remove(); msg.remove();
  const hero=heroC.createInstance(); content.insertChild(0,hero); hero.layoutSizingHorizontal='FILL';
  content.layoutMode='VERTICAL'; content.itemSpacing=16; content.paddingLeft=16; content.paddingRight=16; content.paddingTop=16; content.counterAxisAlignItems='CENTER'; content.primaryAxisSizingMode='AUTO';
  for(const c of content.children){ try{ c.layoutSizingHorizontal='FILL'; }catch(e){} }
  const set=async(name,txt)=>{ const t=hero.findAll(n=>n.type==='TEXT'&&n.name===name)[0]; await figma.loadFontAsync(t.fontName); t.characters=txt; };
  await set('Chip Text',cfg.chip); await set('Title',cfg.title||texts[0]); await set('Sub',cfg.sub); await set('Score',cfg.score);
  const em=hero.findAll(n=>n.type==='INSTANCE'&&n.name==='Grade Emblem')[0]; em.swapComponent(await g(GR[cfg.grade]));
  log[frameId]={texts,kids:content.children.map(c=>c.name)};
}
