const log=[];
// B-10b score 96
const b10b=await g('12152:99499'); const sc=b10b.findAll(n=>n.type==='TEXT'&&n.name==='Score')[0]; await figma.loadFontAsync(sc.fontName); sc.characters='96점';
const nav=(d,tr)=>({trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:d,navigation:'NAVIGATE',transition:tr||{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.25},preserveScrollPosition:false,resetVideoPosition:false}]});
const push=d=>nav(d,{type:'MOVE_IN',direction:'LEFT',matchLayers:false,easing:{type:'EASE_OUT'},duration:0.3});
const W=async(n,r,l)=>{ if(!n){log.push('MISSING '+l);return;} try{ await n.setReactionsAsync([r]); log.push('ok '+l);}catch(e){ log.push('ERR '+l+' '+e.message.slice(0,40)); } };
const B10=await g('12306:99941');
// B-08 확인 필수
const b08=await g('11913:62701');
const btns=b08.findAll(n=>n.type==='INSTANCE'&&n.name==='Block Button');
for(const b of btns){ const t=b.findAll(x=>x.type==='TEXT')[0]?.characters||''; log.push('b08 btn "'+t+'" '+b.id.slice(-12)); if(/맞아요/.test(t)) await W(b,push(B10.id),'B-08 맞아요→B-10'); if(/다른 생명체/.test(t)) await W(b,push('11939:48361'),'B-08 다른생명체→B-08b'); }
const pencil=b08.findAll(n=>/Icon Button|Edit|Pencil/.test(n.name)&&n.type==='INSTANCE'); log.push('b08 icon btns '+pencil.map(p=>p.name+p.id.slice(-10)).join(','));
// close X on B-10 family → list
for(const id of [B10.id,'12152:99433','12152:99499','12231:7001']){ const f=await g(id); const lb=f.findAll(n=>n.name==='Leading Button')[0]; await W(lb,nav('11997:83897'),'X '+id.slice(-6)); }
// B-10b buttons: 대표로 바꾸기 / 그대로 두기 → C-06
const bb=b10b.findAll(n=>n.type==='INSTANCE'&&n.name==='Block Button'); for(const b of bb){ await W(b,push('12256:96670'),'B-10b btn'); }
// start point
const pts=[...figma.currentPage.flowStartingPoints]; pts.splice(2,0,{nodeId:B10.id,name:'Ⓑ 새 종 결과'}); figma.currentPage.flowStartingPoints=pts;
return log;

