const cp=await figma.getNodeByIdAsync('5013:27195'); await figma.setCurrentPageAsync(cp);
const comps=await figma.getNodeByIdAsync('12199:85019');
const head=comps.children.find(c=>c.type==='TEXT'&&c.name.startsWith('heading · 공유'));
await figma.loadFontAsync(head.fontName);
const bottom=Math.max(...comps.children.map(c=>c.y+c.height));
const h=head.clone(); comps.appendChild(h); h.characters='포착 결과'; h.name='heading · 포착 결과'; h.x=head.x; h.y=bottom+100;
await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('5013:27194'));
let x=head.x; const y=h.y+h.height+40;
for(const id of ['12306:99831','12306:99863']){ const n=await figma.getNodeByIdAsync(id); comps.appendChild(n); n.x=x; n.y=y; x+=n.width+80; }
const maxY=Math.max(...comps.children.map(c=>c.y+c.height)), maxX=Math.max(...comps.children.map(c=>c.x+c.width));
comps.resizeWithoutConstraints(Math.max(comps.width,maxX+100),maxY+100);
return 'ok';

